                # score prefers complete coverage; skip if a key has no source at all (shouldn't happen since non-ac covered)
                if None in [v for row in pred for v in row]:
                    cost=999
                else:
                    cost=-min(ph,pv)  # small tile first, ties by smaller max? use area
                cost += (ph*pv)*-1e4 + 0
                if best is None or cost>best[0]: best=(cost,ph,pv,ac,pred)
    return best
