import os,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def f(I):
    H,W=len(I),len(I[0]); best=None
    for ac in set(x for row in I for x in row):
        cnt=sum(row.count(ac) for row in I)
        if cnt<0.05*H*W: continue
        for ph in range(1,W+1):
            for pv in range(1,H+1):
                tiles={}; ok=True
                for r in range(H):
                    for c in range(W):
                        if I[r][c]!=ac:
                            k=(r%pv,c%ph)
                            if k in tiles and tiles[k]!=I[r][c]: ok=False;break
                            tiles[k]=I[r][c]
                    if not ok:break
                if not ok: continue
                if any(k not in tiles for k in [(r%pv,c%ph) for r in range(H) for c in range(W) if I[r][c]!=ac]): continue
                pred=[[tiles.get((r%pv,c%ph)) for c in range(W)] for r in range(H)]
                if any(None in row for row in pred): continue
                cost=-min(ph,pv)
                if best is None or cost>best[0]: best=(-min(ph,pv),ph,pv,ac,pred)
    return best[4] if best else None
